/// <summary>
/// Modify route details dialog class
/// </summary>
class METShipmentUpdateRoutesDialog extends RunBase
{
    DialogField     metRoute;
    DialogFIeld     metRouteStopNum;
    DialogField     confirmedShipDate;

    METRoute        metRouteValue;
    METRouteStopNum metRouteStopNumValue;
    SalesShippingDateConfirmed  confirmedShipDateValue;
    Args            args;
    METOrderTransactionType orderTransactionType;
    container       conShipmentIds;

    // Bug 307324: CB626 TMS Engine step 7 remove orders issue
    container conProcessedLoadLines;

}

Method.Source:
/// <summary>
/// Generate dialog class
/// </summary>
/// <returns>Object</returns>
public Object Dialog()
{
    FormRun     formRun = this.parmArgs().caller();
    Map         map = formRun.getFinalizationHeaderMap();
    Map         lineMap = formRun.getFinalizationLineMap();
    Dialog      dialog;

    if (args.dataset() == tableNum(METSalesOrderShipmentLoadHeader) && map.empty())
    {
        throw error("@MET:NoRecordUpdate");
    }

    if (args.dataset() == tableNum(METSalesOrderShipmentLoadLines) && lineMap.empty())
    {
        throw error("@MET:NoRecordUpdate");
    }

    dialog = super();

    dialog.caption( "@MET:RouteChange");

    metRoute            = dialog.addField( extendedTypeStr(METRoute), "@SYS4190");
    metRouteStopNum     = dialog.addField( extendedTypeStr(METRouteStopNum), "@MET:METRouteStop");
    confirmedShipDate   = dialog.addField( extendedTypeStr(SalesShippingDateConfirmed), "@MET:METConfirmedShippingDate");

    dialog.formBuildDesign().dialogSize(0);
    metRouteStopNum.limitText(2);

    if (args.dataset() == tableNum(METSalesOrderShipmentLoadHeader) && map.elements() > 1)
    {
        metRouteStopNum.enabled(false);
    }

    return dialog;
}

/// <summary>
/// Get the values from dialog
/// </summary>
/// <returns>Boolean values</returns>
public boolean getFromDialog()
{
    boolean ret;

    metRouteValue           = metRoute.value();
    metRouteStopNumValue    = metRouteStopNum.value();
    confirmedShipDateValue  = confirmedShipDate.value();

    this.validateRouteDetails();

    ret = super();

    if (metRouteValue != "")
    {
        int     lenRoute        = strLen(metRouteValue);
        int     posRoute        = lenRoute;
        str     lastFourDigit   = subStr(metRouteValue, posRoute, -4);

        METValidateRouteHelper validateRoute = new METValidateRouteHelper();

        if (!validateRoute.validateRouteForUpperCase(metRouteValue) || !validateRoute.validateRouteLength(lenRoute) ||
            !validateRoute.validateForAlphaNumeric(metRouteValue))
        {
            ret = false;
        }

    }

    return ret;
}

/// <summary>
/// Parameter args method
/// </summary>
/// <param name = "_args">Args reference</param>
/// <returns>Args</returns>
public Args parmArgs(Args   _args = args)
{
    args = _args;

    return args;
}

/// <summary>
/// Order transaction type parameter
/// </summary>
/// <param name = "_orderTransactionType">Order transaction type</param>
/// <returns>METOrderTransactionType</returns>
public METOrderTransactionType parmOrderType(METOrderTransactionType        _orderTransactionType = orderTransactionType)
{
    orderTransactionType = _orderTransactionType;

    return orderTransactionType;
}

/// <summary>
/// Method to run the shipment load creation logic
/// </summary>
/// <param name = "_orderNumSet">Set for order num</param>
public void runShipmentLoadCreationLogic(Set     _orderNumSet)
{
    METOrderShipmentLoadCreation        shipmentLoadCreation;
    SetEnumerator       setEnumerator = _orderNumSet.getEnumerator();
    MetShipmentId       metShipmentId;

    setEnumerator.reset();
    while (setEnumerator.moveNext())
    {
        METOrderReference   orderReference;

        ttsbegin;
        orderReference = setEnumerator.current();

        shipmentLoadCreation = METOrderShipmentLoadCreation::construct(this.parmOrderType(), orderReference);
        metShipmentId = shipmentLoadCreation.createShippmentLoad(true, false);

        conShipmentIds += metShipmentId;
        METSalesOrderShipmentLoadHeader::cleanShipmentIfNoLines(conShipmentIds);
        METSalesOrderShipmentLoadHeader::updatePickComplete(conShipmentIds); // 415555 Updateing pick complete
        ttscommit;

    }
}

/// <summary>
/// Run method for business logic
/// </summary>
public void run()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    FormRun                             formRun = this.parmArgs().caller();
    Map                                 map;
    MapIterator                         mapIterator;
    Set                                 orderNumCombineSet = new Set(Types::String);
    Set                                 orderNumSet;
    Set                                 loadSet = new Set(Types::String);
    container                           conTMSUpdate;
    int                                 i;  

    if (args.dataset() == tableNum(METSalesOrderShipmentLoadHeader))
    {
        try
        {
            ttsbegin;
            map = formRun.getFinalizationHeaderMap();

            mapIterator = new MapIterator (map);

            while (mapIterator.more())
            {
                MetLoadId loadId;

                metSalesOrderShipmentLoadHeader = metSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key(), true);

                loadId = metSalesOrderShipmentLoadHeader.LoadId;

                if (metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open)
                {
                    // Bug 307324: CB626 TMS Engine step 7 remove orders issue
                    // add all load lines related to this shipment to the container for TMS update 
                    // if only route stop updated skip this part as TMS not affected
                    if (orderTransactionType == METOrderTransactionType::SalesOrder
                    && (metRouteValue || confirmedShipDateValue))
                    {
                        METSalesOrderShipmentLoadLines loadlines;
                        while select OrderNum, PickingListNum from loadlines
                               where loadlines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
                        {
                            i++;
                            conTMSUpdate = conIns(conTMSUpdate, i, [loadlines.OrderNum, loadlines.PickingListNum]);
                        }
                    }

                    orderNumCombineSet = Set::union(orderNumCombineSet, metSalesOrderShipmentLoadHeader.updateRouteInformation(confirmedShipDateValue, metRouteValue, metRouteStopNumValue));

                    if (conFind(conShipmentIds, metSalesOrderShipmentLoadHeader.ShipmentId) == 0)
                    {
                        conShipmentIds += [metSalesOrderShipmentLoadHeader.ShipmentId];
                    }

                    if (loadSet.in(loadId) == false)
                    {
                        loadSet.add(loadId);
                    }

                }
                else
                {
                    warning(strFmt("@MET:ShipmentStatusValid", metSalesOrderShipmentLoadHeader.ShipmentId));
                }
                mapIterator.next();
            }

            if (!orderNumCombineSet.empty())
            {
                this.runShipmentLoadCreationLogic(orderNumCombineSet);
            }

            if (!loadSet.empty())
            {
                this.processLoadStatusUpdate(loadSet);
            }

            ttscommit;
            info("@MET:UpdateShipment");                
        }
        catch
        {
            exceptionTextFallThrough();
        }
    }
    else if (args.dataset() == tableNum(METSalesOrderShipmentLoadLines))
    {
        try
        {
            MetShipmentId shipmentId;
            WMSPickingRouteID pickingListNum;

            ttsbegin;
            map = formRun.getFinalizationLineMap();
            //orderTransactionType = formRun.getOrderTranscationType();
            mapIterator = new MapIterator(map);

            while (mapIterator.more())
            {
                ttsbegin;

                if (mapIterator.key() != '')
                {
                    orderNumCombineSet.add(mapIterator.key());

                    if (orderTransactionType == METOrderTransactionType::SalesOrder)
                    {
                        METSalesOrderShipmentLoadHeader::updateSalesTableAndShipment(mapIterator.key(), confirmedShipDateValue, metRouteValue, metRouteStopNumValue);

                        // Bug 307324: CB626 TMS Engine step 7 remove orders issue
                        // reselect load line as it's grouped by order num and shipment id in workbench form
                        METSalesOrderShipmentLoadLines loadLines;
                        select firstonly OrderNum, PickingListNum from loadLines
                                   where loadLines.ShipmentId == mapIterator.value() &&
                                         loadLines.OrderNum == mapIterator.key();

                        if (loadLines && (metRouteValue || confirmedShipDateValue))
                        {
                            i++;
                            conTMSUpdate = conIns(conTMSUpdate, i, [loadLines.OrderNum, loadLines.PickingListNum]);
                        }
                    }
                    else
                    {
                        METSalesOrderShipmentLoadHeader::updateTransferOrderAndShipment(mapIterator.key(), confirmedShipDateValue, metRouteValue, metRouteStopNumValue);
                    }

                    if (conFind(conShipmentIds, mapIterator.value()) == 0)
                    {
                        conShipmentIds += [mapIterator.value()];

                        METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoad = METSalesOrderShipmentLoadHeader::findByShipmentId(mapIterator.value());

                        if (loadSet.in(metSalesOrderShipmentLoad.LoadId) == false)
                        {
                            loadSet.add(metSalesOrderShipmentLoad.LoadId);
                        }
                    }
                }
                ttscommit;

                mapIterator.next();
            }

            if (!orderNumCombineSet.empty())
            {
                this.runShipmentLoadCreationLogic(orderNumCombineSet);
            }

            if (!loadSet.empty())
            {
                this.processLoadStatusUpdate(loadSet);
            }

            ttscommit;
            info("@MET:UpdateShipment");
        }
        catch
        {
            exceptionTextFallThrough();
        }

        try
        {
            // Bug 307324: CB626 TMS Engine step 7 remove orders issue
            this.updateTMSEngine(conTMSUpdate);
        }
        catch
        {
            exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Main method for the class
/// </summary>
/// <param name = "_args">Args reference</param>
public static void main(Args _args)
{
    METShipmentUpdateRoutesDialog metShipmentUpdateRoutesDialog = new METShipmentUpdateRoutesDialog();

    metShipmentUpdateRoutesDialog.parmOrderType(_args.parmEnum());
    metShipmentUpdateRoutesDialog.parmArgs(_args);

    Boolean isOkOrCancelledClicked = metShipmentUpdateRoutesDialog.prompt();
    if (isOkOrCancelledClicked)
    {
        metShipmentUpdateRoutesDialog.run();
    }

    FormRun  metSalesOrderFinalizationWorkbenchFormRun = _args.caller() as FormRun;
    if (metSalesOrderFinalizationWorkbenchFormRun)
    {
        metSalesOrderFinalizationWorkbenchFormRun.hasUpdateRouteRunOrCancelled(isOkOrCancelledClicked);
    }
}

/// <summary>
/// Validation before processing business logic
/// </summary>
public void validateRouteDetails()
{
    if (metRouteValue == "" && metRouteStopNumValue == 0 && confirmedShipDateValue == dateNull())
    {
        throw error("@MET:UpdateCancelled");
    }

    if (confirmedShipDateValue != dateNull() && confirmedShipDateValue < DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
    {
        throw error("@MET:ShipDateNotConfirmed");
    }

    if (metRouteStopNumValue != 0)
    {
        int     lenRouteStop    = strLen(int2Str(metRouteStopNumValue));

        if (lenRouteStop > 2)
        {
            throw error("@MET:InvalidFormatRouteStop99");
        }
    }        
}

/// <summary>
/// Process load status update
/// </summary>
/// <param name = "_loadSet">LoadSet </param>
public void processLoadStatusUpdate(Set _loadSet)
{
    SetEnumerator setEnumerator = _loadSet.getEnumerator();

    while (setEnumerator.moveNext())
    {
        METSalesOrderShipmentLoadHeader::updateLoadStatus(setEnumerator.current());
    }
}

/// <summary>
/// Bug 307324: CB626 TMS Engine step 7 remove orders issue
/// Delete old TSO and retrigger TMS engine pick list
/// </summary>
protected void updateTMSEngine(container _conTSMUpdate)
{
    METOrderNumber      orderNumber;
    WMSPickingRouteID   pickingRouteID;

    for (int i = 1; i <= conLen(_conTSMUpdate); i++)
    {
        [orderNumber, pickingRouteID]= conPeek(_conTSMUpdate, i);

        WMSPickingRoute    wmsPickingRoute = WMSPickingRoute::find(pickingRouteID);

        if (wmsPickingRoute)
        {
            // For the load or lines, delete the corresponding TMS shipment orders using orderNum and picking list number combination
            METTMSShipmentID TMSShipmentId = METTMSEngineOrderProccess::deleteTMSShipmentOrderTable(orderNumber, pickingRouteID);

            ttsbegin;
            METTMSEngineOrderProccess  metTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderPickingList, wmsPickingRoute, wmsPickingRoute.PickingRouteID);

            // retrigger the pallet calculation for the TMS shipment where an order was deleted
            metTMSEngineOrderProccess.updateTMSShipment(TMSShipmentId);

            // retrigger the TMS engine for the order/picking list to recreate a new TMS shipment or add the order/picklist to an existing TMS shipment.
            metTMSEngineOrderProccess.run();
            ttscommit;
        }
    }
}
